    unsigned long long last_page_index =
        (file_size + page_size - 1) / page_size - 1;
    return page_index == last_page_index;
}

/*
 * Baseline: pure LFU (mimics cache_ext_sampling.bpf.c bpf_lfu_score_fn).
 * Kernel picks LOWEST score in each batch. S64_MAX = never prefer as victim.
 * Evolution can add vulcan_get_* calls and protection rules.
 */
static s64 bpf_score_fn(struct cache_ext_list_node *node)
{
    struct folio *folio = node->folio;
    if (!folio)
        return S64_MAX;

    if (folio_test_dirty(folio) || folio_test_writeback(folio))
        return S64_MAX;
    if (!folio_test_uptodate(folio) || !folio_test_lru(folio))
        return S64_MAX;

    u64 key = (u64)folio;
    struct vulcan_folio_metadata *meta =
        bpf_map_lookup_elem(&folio_metadata_map, &key);
    if (!meta)
        return S64_MAX;

    // Base score: access count (higher = keep)
    s64 score = (s64)meta->access_count;

    // Network-aware protection: when RTT is high, cache misses are expensive
    // RTT is in usec; typical good RTT < 10ms (10000us), bad > 50ms (50000us)
    s64 rtt_ewma = vulcan_get_ewma(GF_SRTT_US);
    if (rtt_ewma > 50000) {
        // High RTT: add bonus to protect frequently accessed pages
        score += meta->access_count / 2;
    } else if (rtt_ewma > 35000) {
        // Intermediate RTT: 37.5% bonus (3/8)
        score += (meta->access_count * 3) / 8;
    } else if (rtt_ewma > 20000) {
        // Moderate RTT: small bonus
        score += meta->access_count / 4;
    }

    // Loss detection: if we've seen packet loss, be conservative
    s64 lost_max = vulcan_get_max(GF_LOST);
    if (lost_max > 0) {
        // Network congestion: protect working set
        score += meta->access_count / 3;
    }

    // Per-folio heat: lower interval EWMA = hotter (more frequent accesses)
    // Interval is in nanoseconds; < 100ms (100000000ns) = hot
    s64 interval_ewma = meta->interval_ewma.value;
    if (interval_ewma > 0 && interval_ewma < 100000000) {
        // Hot folio: frequently re-accessed, add bonus
        score += 5000;
    } else if (interval_ewma > 0 && interval_ewma < 1000000000) {
        // Warm folio: < 1 second interval
        score += 2000;
    }

    // Continuous variance-weighted regularity scoring for hot folios
    // Uses safe arithmetic (multiplication and bit shifts) instead of division
    // Rewards highly predictable access patterns (low variance) more than irregular ones
    // Particularly important for LevelDB's sequential index scans with extremely low variance
    s64 interval_min = meta->interval_minmax.min_val;
    s64 interval_max = meta->interval_minmax.max_val;
    if (interval_ewma > 0 && interval_ewma < 100000000 && interval_min > 0 && interval_max > 0) {
        // Only for hot folios (interval_ewma < 100ms)
        s64 variance = interval_max - interval_min;
        if (variance < interval_ewma) {
            // Continuous regularity bonus: higher for lower variance
            // Safe arithmetic: (5000 * diff) >> 32 scales appropriately
            s64 regularity_diff = interval_ewma - variance;
            s64 regularity_bonus = (5000 * regularity_diff) >> 32;
            if (regularity_bonus > 0) {
                score += regularity_bonus;
            }
        }
    }

    // Recency: protect recently accessed folios (likely in working set)
    // During congestion (packet loss), increase bonuses to be more conservative
    // and extend protection window to capture working set during sustained stress
    // High jitter (RTT variance) also extends working set window due to unpredictable latency
    u64 now = bpf_ktime_get_ns();
    s64 age = (s64)(now - meta->last_access_ts);
    s64 mdev_ewma = vulcan_get_ewma(GF_MDEV_US);
    bool high_jitter = (mdev_ewma > 10000);  // > 10ms jitter = high variance

    // Primary recency tier: extend from 5s to 7s under high jitter
    s64 primary_threshold = high_jitter ? 7000000000 : 5000000000;
    if (age < primary_threshold) {
        if (lost_max > 0) {
            score += 4500;  // 50% bonus during congestion
        } else {
            score += 3000;
        }
    } else if (age < 30000000000) {  // < 30 seconds
        // Increase bonus under high jitter to capture expanded working set
        s64 base_bonus = high_jitter ? 1200 : 1000;
        if (lost_max > 0) {
            score += base_bonus + 500;  // 50% bonus during congestion
        } else {
            score += base_bonus;
        }
    } else if (age < 60000000000) {  // < 60 seconds
        if (lost_max > 0) {
            score += 500;  // Extended protection during congestion
        }
    }

    // LevelDB: protect index block (last page of file)
    if (is_last_page_in_file(folio))
        score += 100000;

    return score;
}

// -- struct_ops: init ---------------------------------------------------------
s32 BPF_STRUCT_OPS_SLEEPABLE(evolved_init, struct mem_cgroup *memcg)
{
    main_list = bpf_cache_ext_ds_registry_new_list(memcg);
    if (!main_list)
        return -1;
    return 0;
}

// -- struct_ops: evict_folios -------------------------------------------------
void BPF_STRUCT_OPS(evolved_evict_folios,
                    struct cache_ext_eviction_ctx *eviction_ctx,
                    struct mem_cgroup *memcg)
{
    bump_counter(0);
    struct sampling_options opts = { .sample_size = SAMPLE_SIZE };
    bpf_cache_ext_list_sample(memcg, main_list, bpf_score_fn, &opts,
                  eviction_ctx);
}

// -- struct_ops: folio_added --------------------------------------------------
void BPF_STRUCT_OPS(evolved_folio_added, struct folio *folio)
{
    if (!is_folio_relevant(folio))
        return;

    int ret = bpf_cache_ext_list_add_tail(main_list, folio);
    if (ret != 0) {
        bump_counter(1);
        return;
    }

    u64 key = (u64)folio;
    struct vulcan_folio_metadata new_meta =
        vulcan_folio_init(bpf_ktime_get_ns());
    bpf_map_update_elem(&folio_metadata_map, &key, &new_meta, BPF_ANY);
    bump_counter(2);
}

// -- struct_ops: folio_accessed -----------------------------------------------
void BPF_STRUCT_OPS(evolved_folio_accessed, struct folio *folio)
{
    if (!is_folio_relevant(folio))
        return;

    u64 key = (u64)folio;
    struct vulcan_folio_metadata *meta =
        bpf_map_lookup_elem(&folio_metadata_map, &key);

    if (!meta) {
        int ret = bpf_cache_ext_list_add(main_list, folio);
        if (ret != 0)
            bpf_cache_ext_list_move(main_list, folio, false);
        struct vulcan_folio_metadata new_meta =
            vulcan_folio_init(bpf_ktime_get_ns());
        bpf_map_update_elem(&folio_metadata_map, &key, &new_meta, BPF_ANY);
        bump_counter(3);
        return;
    }

    vulcan_folio_on_access(meta, bpf_ktime_get_ns(), &folio_cfg);
    bump_counter(4);
}

// -- struct_ops: folio_evicted ------------------------------------------------
void BPF_STRUCT_OPS(evolved_folio_evicted, struct folio *folio)
{
    if (!is_folio_relevant(folio))
        return;

    u64 key = (u64)folio;
    bpf_map_delete_elem(&folio_metadata_map, &key);
    bump_counter(5);
}

