    raw_values[GF_SEGS_IN]        = (s64)net_segs_in;
    raw_values[GF_SEGS_OUT]       = (s64)net_segs_out;
    raw_values[GF_DELIVERED]      = (s64)net_delivered;
    raw_values[GF_BYTES_RECEIVED] = (s64)net_bytes_received;
