//
//   vulcan_get_min(GF_xxx)              -- observed minimum  (needs MINMAX)
//   vulcan_get_max(GF_xxx)              -- observed maximum  (needs MINMAX)
//   vulcan_get_ewma(GF_xxx)             -- EWMA value        (needs EWMA)
